// JPEG bytes for logo tests, with no image library at test time.

/** A real 16 x 8 baseline JPEG of one solid colour, encoded once with Pillow and pasted as hex. */
export const SOLID_JPEG_16X8 = Uint8Array.from(
  Buffer.from(
    '',
    'hex',
  ),
);

/** SOI, a SOF0 header with the given size and three components, then EOI: what a truncated upload can look like. */
export function jpegHeaderOnly(width: number, height: number): Uint8Array {
  return new Uint8Array([
    0xff, 0xd8, 0xff, 0xc0, 0x00, 0x11, 0x08, height >> 8, height & 0xff, width >> 8, width & 0xff, 0x03,
    0x01, 0x22, 0x00, 0x02, 0x11, 0x01, 0x03, 0x11, 0x01, 0xff, 0xd9,
  ]);
}
